pub fn searchMemory(haystack: []const u8, needle: []const u8) ?usize {
    if (needle.len == 0 or needle.len > haystack.len) return null;

    outer: for (0..haystack.len - needle.len + 1) |i| {
        for (needle, 0..) |n, j| {
            if (haystack[i + j] != n) continue :outer;
        }
        return i;
    }

    return null;
}

