    for (b) |c| try set_b.put(c, {});

    var diff = std.ArrayList(u8).init(allocator);
    defer diff.deinit();

    for (a) |c| {
        if (!set_b.contains(c)) try diff.append(c);
    }

    return diff.toOwnedSlice();
}

