pub fn canaryProtect(ptr: *anyopaque, size: usize) void {
    if (size < 8) return;

    const canary: u32 = 0xDEADBEEF;
    const base = @as([*]u8, @ptrCast(ptr));

    const before: *u32 = @ptrCast(@alignCast(base - 4));
    const after: *u32 = @ptrCast(@alignCast(base + size));

    before.* = canary;
    after.* = canary;
}

pub fn checkCanary(ptr: *anyopaque, size: usize) bool {
