pub fn splitMemory(allocator: Allocator, data: []const u8, delim: u8) ![][]const u8 {
    var count: usize = 1;
    for (data) |c| {
        if (c == delim) count += 1;
    }

    const parts = try allocator.alloc([]const u8, count);
    var start: usize = 0;
    var i: usize = 0;

    for (data, 0..) |c, j| {
        if (c == delim) {
            parts[i] = data[start..j];
            start = j + 1;
            i += 1;
        }
    }

    if (i < count) {
        parts[i] = data[start..];
    }

    return parts;
}

