pub fn stringInterning(pool: *std.StringHashMap(void), str: []const u8) ![]const u8 {
    if (pool.contains(str)) {
        var iter = pool.iterator();
        while (iter.next()) |entry| {
            if (mem.eql(u8, entry.key_ptr.*, str)) {
                return entry.key_ptr.*;
            }
        }
    }

    try pool.put(str, {});
    return str;
}

